package com.campus.trade.dispute.controller; import com.campus.trade.common.response.*; import com.campus.trade.dispute.dto.HandleDisputeRequest; import com.campus.trade.dispute.service.DisputeService; import com.campus.trade.dispute.vo.AdminDisputeVO; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*;
/** 管理员纠纷列表与裁决接口；/admin/** 已由 AdminInterceptor 保护。 */ @Validated @RestController @RequestMapping("/admin/disputes") public class AdminDisputeController {private final DisputeService service;public AdminDisputeController(DisputeService s){service=s;}@GetMapping public Result<PageResult<AdminDisputeVO>> list(@RequestParam(required=false) @Min(0) @Max(4) Integer status,@RequestParam(defaultValue="1") @Min(1) int page,@RequestParam(defaultValue="10") @Min(1) @Max(50) int pageSize){return Result.ok(service.list(status,page,pageSize));}@PostMapping("/{id}/handle") public Result<Void> handle(@PathVariable @Min(1) Long id,@Valid @RequestBody HandleDisputeRequest r){service.handle(id,r);return Result.ok();}}
